{# =======================
  EMPLOYEE NOMINATION - PRINT FORMAT
  Map fields as per your Doctype
======================= #}

{% set base_url = frappe.utils.get_url() %}

{# --- Suggested field mappings (change as per your doctype) --- #}
{% set emp_name = doc.employee_name or doc.applicant_name or doc.employee or "" %}
{% set emp_no   = doc.employee_code or doc.emp_no or doc.employee or "" %}
{% set desig    = doc.designation or "" %}
{% set dept     = doc.department or "" %}
{% set dated    = frappe.utils.formatdate(doc.posting_date or doc.date or frappe.utils.nowdate()) %}

{% set father_spouse = doc.father_or_spouse_name or doc.son_daughter_wife_of or "" %}

{% set nominee_name   = doc.nominee_name or "" %}
{% set nominee_father = doc.nominee_father_or_spouse or doc.nominee_son_daughter_wife_of or "" %}
{% set nominee_relation = doc.nominee_relation or doc.relationship_with_nominee or "" %}
{% set nominee_nic     = doc.nominee_cnic or doc.nominee_nic or "" %}

{% set emp_nic = doc.employee_cnic or doc.emp_cnic or "" %}

{% set w1_name = doc.witness_1_name or "" %}
{% set w1_nic  = doc.witness_1_nic or "" %}
{% set w1_addr = doc.witness_1_address or "" %}

{% set w2_name = doc.witness_2_name or "" %}
{% set w2_nic  = doc.witness_2_nic or "" %}
{% set w2_addr = doc.witness_2_address or "" %}

<style>
  @page { size: A4; margin: 12mm; }
  .print-format { font-family: Arial, sans-serif; font-size: 11px; color:#000; }
  .sheet{ border:1px solid #000; padding:10px 12px 12px; }

  .top{
    display:flex; align-items:center; gap:12px; margin-bottom:8px;
  }
  .logo{
    width:55px; height:55px; object-fit:contain;
  }
  .title{
    flex:1; text-align:center;
  }
  .title h1{ margin:0; font-size:16px; letter-spacing:.8px; }
  .title h2{ margin:2px 0 0; font-size:14px; letter-spacing:3px; text-decoration:underline; }

  .row{ display:flex; gap:10px; align-items:flex-end; margin-top:8px; flex-wrap:wrap; }
  .field{ flex:1; min-width:180px; }
  .label{ font-weight:700; }
  .line{
    border-bottom:1px solid #000;
    min-height:14px;
    padding:0 4px 1px;
    display:inline-block;
    width:100%;
  }
  .line.inline{ width:auto; min-width:140px; }
  .muted{ font-style:italic; font-size:10px; }
  .para{ margin-top:10px; line-height:1.4; }

  .box{
    border:1px solid #000;
    height:22px;
    padding:2px 6px;
    display:flex;
    align-items:center;
    justify-content:flex-start;
    margin-top:6px;
  }

  .grid2{
    display:grid;
    grid-template-columns: 1fr 1fr;
    gap:12px;
    margin-top:12px;
  }
  .sig-title{
    font-weight:700;
    text-align:center;
    border-bottom:1px solid #000;
    padding-bottom:6px;
    margin-bottom:10px;
  }
  .sig-box{
    border:1px solid #000;
    height:60px;
  }
  .sig-meta{
    margin-top:8px;
    display:flex;
    gap:10px;
    align-items:center;
  }
  .sig-meta .small{ font-weight:700; width:80px; }
  .sig-meta .nicbox{ border:1px solid #000; height:22px; flex:1; }

  .witness-wrap{ margin-top:12px; }
  .wtitle{ font-weight:700; margin-top:12px; }
  .wblock{ margin-top:6px; }
  .wline{ border-bottom:1px solid #000; min-height:14px; padding:0 4px 1px; display:inline-block; width:75%; }
  .wnicbox{ border:1px solid #000; height:22px; display:inline-block; width:200px; vertical-align:bottom; }
  .wsig{ border-top:1px solid #000; width:220px; margin-top:16px; text-align:center; padding-top:4px; font-size:10px; float:right; }

  .clear{ clear:both; }
</style>

<div class="sheet">

  <div class="top">
    <img class="logo" src="https://erp.theilmfoundation.cloud/files/454985247_461775626827401_330977418181804304_n.jpg" alt="Logo">
    <div class="title">
      <h1>EMPLOYEE</h1>
      <h2>N O M I N A T I O N</h2>
    </div>
    <div style="width:160px; text-align:right;">
      <span class="label">Dated:</span>
      <span class="line inline">{{ dated }}</span>
    </div>
  </div>

  <div class="row">
    <div class="field">
      I, <span class="line inline" style="min-width:260px;">{{ doc.first_name }}</span>

      <span class="line inline" style="min-width:260px;">{{ doc.last_name }}</span>
      <div class="muted">Son/Daughter/Wife of</div>
    </div>
  </div>

  <div class="row">
    <div class="field">
      <span class="label">Emp. No</span>
      <span class="line inline" style="min-width:160px;">{{ emp_no }}</span>
    </div>
    <div class="field">
      <span class="label">Designation</span>
      <span class="line inline" style="min-width:200px;">{{ desig }}</span>
    </div>
    <div class="field">
      <span class="label">Dept.</span>
      <span class="line inline" style="min-width:180px;">{{ dept }}</span>
    </div>
  </div>

  <div class="para">
    do hereby nominate Mr./Mrs./Miss.
<span class="line inline" style="min-width:360px;">{{ doc.next_of_kin_first_name }}</span>
  </div>

  <div class="para">
    <span class="line inline" style="min-width:380px;">{{ doc.next_of_kin_last_name }}</span>
    <div class="muted">Son/Daughter/Wife of</div>
  </div>

  <div class="para">
    <span class="line inline" style="min-width:380px;">{{ doc.relationship }}</span>
    <div class="muted">(Relation with the Nominee)</div>
  </div>

  <div class="para">
    <span class="label">N.I.C. No.</span>
    <div class="box">{{ doc.cnic }}</div>
  </div>

  <div class="para">
    Who has attained his/her majority to be <b>NOMINEE</b> to receive in the event of my death the amount of
    all my dues, e.g. Salary, Allowances etc.<br>
    Accounts and all other benefits of whatsoever nature.
  </div>

  <div class="para">
    The specimen signature of my <b>NOMINEE</b> is given below and his/her National Identity Card's photo copy is enclosed.
  </div>

  <div class="grid2">
    <div>
      <div class="sig-title">SPECIMEN SIGNATURE OF<br>NOMINEE</div>
      <div class="sig-box"></div>
    </div>
    <div>
      <div class="sig-title">EMPLOYEE'S<br>SIGNATURE</div>
      <div class="sig-box"></div>

      <div class="sig-meta">
        <div class="small">Emp NIC No.</div>
        <div class="nicbox" style="display:flex; align-items:center; padding:0 6px;">
          {{ emp_nic }}
        </div>
      </div>
    </div>
  </div>

  <div class="witness-wrap">
    <div class="wtitle">WITNESSES:</div>

    <div class="wblock">
      <div><b>(1)</b> Name: <span class="wline">{{ doc.w_1_name }}</span></div>
      <div style="margin-top:6px;"><b>Address:</b> <span class="wline">{{ doc.w_1_address }}</span></div>

      <div style="margin-top:10px; display:flex; justify-content:space-between; align-items:flex-end;">
        <div><b>Witness (1) NIC No.</b> <span class="wnicbox" style="padding:2px 6px;">{{ doc.w_1_cnic }}</span></div>
        <div class="wsig">Witness (1) Signature</div>
      </div>
      <div class="clear"></div>
    </div>

    <div class="wblock" style="margin-top:18px;">
      <div><b>(2)</b> Name: <span class="wline">{{ doc.w_2_name }}</span></div>
      <div style="margin-top:6px;"><b>Address:</b> <span class="wline">{{ doc.w_2_address }}</span></div>

      <div style="margin-top:10px; display:flex; justify-content:space-between; align-items:flex-end;">
        <div><b>Witness (2) NIC No.</b> <span class="wnicbox" style="padding:2px 6px;">{{ doc.w_2_cnic }}</span></div>
        <div class="wsig">Witness (2) Signature</div>
      </div>
      <div class="clear"></div>
    </div>
  </div>

</div>
